// CompareNote is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareNote(before, after foundryvalue.Optional[Note], assigned NoteDraft) (NoteChanges, error) {
	before = foundryNoteSnapshot(before)
	after = foundryNoteSnapshot(after)
	var changes NoteChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Note](), before, after, assigned.fieldID.IsSet(), func(item Note) model.ID[Note] { return item.ID })
	if err != nil {
		return NoteChanges{}, fmt.Errorf("compare Note.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return NoteChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.SubjectType, err = lifecycle.CompareModelField(codec.String[foundryquery.MorphName](), before, after, assigned.fieldSubjectType.IsSet(), func(item Note) foundryquery.MorphName { return item.SubjectType })
	if err != nil {
		return NoteChanges{}, fmt.Errorf("compare Note.SubjectType: %w", err)
	}
	changes.fields.SubjectID, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldSubjectID.IsSet(), func(item Note) string { return item.SubjectID })
	if err != nil {
		return NoteChanges{}, fmt.Errorf("compare Note.SubjectID: %w", err)
	}
	changes.fields.Body, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldBody.IsSet(), func(item Note) string { return item.Body })
	if err != nil {
		return NoteChanges{}, fmt.Errorf("compare Note.Body: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
