// NoteRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type NoteRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Note) error
}

// NoteRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type NoteRetrievalObserver = lifecycle.Observer[Note, NoteRetrievalHooks]

// NewNoteRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewNoteRetrievalObserver(observer string) NoteRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Note, NoteRetrievalHooks](observer)
}

// RegisterNoteRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterNoteRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer NoteRetrievalObserver, construct func(foundation.Resolver) (func() NoteRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (NoteRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Note], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Note, NoteRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Note]{}, err
	}
	var allHooks []NoteRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Note]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Note]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Note]{}, err
	}
	return foundryquery.RetrievalHooks[Note]{Retrieved: func(ctx context.Context, executor database.Executor, item Note) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// NoteAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type NoteAuditPolicy struct {
	_ [0]*Note
	// ID controls the audit representation of stored office_notes.id.
	ID record.Disclosure
	// SubjectType controls the audit representation of stored office_notes.subject_type.
	SubjectType record.Disclosure
	// SubjectID controls the audit representation of stored office_notes.subject_id.
	SubjectID record.Disclosure
	// Body controls the audit representation of stored office_notes.body.
	Body record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes NoteChanges) Audit(policy NoteAuditPolicy) (record.Model[Note, model.ID[Note]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Note, model.ID[Note]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Note, model.ID[Note]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Note, model.ID[Note]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Note](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Note, model.ID[Note]]{}, err
	}
	if err = record.Capture(builder, "subject_type", codec.String[foundryquery.MorphName](), changes.fields.SubjectType, policy.SubjectType); err != nil {
		return record.Model[Note, model.ID[Note]]{}, err
	}
	if err = record.Capture(builder, "subject_id", codec.String[string](), changes.fields.SubjectID, policy.SubjectID); err != nil {
		return record.Model[Note, model.ID[Note]]{}, err
	}
	if err = record.Capture(builder, "body", codec.String[string](), changes.fields.Body, policy.Body); err != nil {
		return record.Model[Note, model.ID[Note]]{}, err
	}
	return builder.Build()
}

// NoteAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type NoteAuditFieldSet struct {
	_ [0]*Note
	// ID retains stored office_notes.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record.FieldChange[model.ID[Note]]]
	// SubjectType retains stored office_notes.subject_type after write mutators; read accessors do not replace audit values.
	SubjectType foundryvalue.Optional[record.FieldChange[foundryquery.MorphName]]
	// SubjectID retains stored office_notes.subject_id after write mutators; read accessors do not replace audit values.
	SubjectID foundryvalue.Optional[record.FieldChange[string]]
	// Body retains stored office_notes.body after write mutators; read accessors do not replace audit values.
	Body foundryvalue.Optional[record.FieldChange[string]]
}

// NoteAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func NoteAuditFields(history record.Model[Note, model.ID[Note]]) (NoteAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return NoteAuditFieldSet{}, err
	}
	var fields NoteAuditFieldSet
	fields.ID, err = record.ReadField(view, "id", codec.ID[Note]())
	if err != nil {
		return NoteAuditFieldSet{}, err
	}
	fields.SubjectType, err = record.ReadField(view, "subject_type", codec.String[foundryquery.MorphName]())
	if err != nil {
		return NoteAuditFieldSet{}, err
	}
	fields.SubjectID, err = record.ReadField(view, "subject_id", codec.String[string]())
	if err != nil {
		return NoteAuditFieldSet{}, err
	}
	fields.Body, err = record.ReadField(view, "body", codec.String[string]())
	if err != nil {
		return NoteAuditFieldSet{}, err
	}
	return fields, nil
}

// NoteAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func NoteAuditing(policy NoteAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Note]()
		if err != nil {
			return err
		}
		return RegisterNoteObserver(registrar, pool, NewNoteObserver(name), func(resolver foundation.Resolver) (func() NoteHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() NoteHooks {
				write := func(ctx context.Context, tx *database.Tx, changes NoteChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return NoteHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
